const pet=document.querySelector('#pet'),room=document.querySelector('.room'),bubble=document.querySelector('#bubble'),mood=document.querySelector('#mood'),icon=document.querySelector('#stateIcon');let sleeping=false,timer,down=null,moved=false;
function animate(name){pet.classList.remove('happy','play');void pet.offsetWidth;pet.classList.add(name);clearTimeout(timer);timer=setTimeout(()=>pet.classList.remove(name),2300)}
function hearts(){for(let i=0;i<4;i++){const h=document.createElement('span');h.className='heart';h.textContent='♡';h.style.color=['#e77f92','#e69a60','#5986c0'][i%3];h.style.left=(pet.offsetLeft+65+Math.random()*100)+'px';h.style.top=(pet.offsetTop+35+Math.random()*65)+'px';document.querySelector('#hearts').append(h);setTimeout(()=>h.remove(),1600)}}
function act(action){if(!['pet','feed','play','sleep'].includes(action))throw new Error('不支持的互动');if(action==='sleep'){sleeping=!sleeping;pet.classList.toggle('sleeping',sleeping);document.querySelector('#sleepLabel').textContent=sleeping?'叫醒小八':'睡个小觉';bubble.textContent=sleeping?'呼噜…晚安，待会儿见。':'睡饱啦，陪你玩～';mood.textContent=sleeping?'正在做甜甜的梦':'精神满满';icon.textContent=sleeping?'☾':'♡';}else{if(sleeping){bubble.textContent='嘘…小八正在睡觉，先叫醒它吧。';return {sleeping,mood:mood.textContent}}const lines={pet:['哇～你的手好暖呀。','再摸一下，就一下～','最喜欢和你待在一起。'],feed:['啊呜！好吃！谢谢你～'],play:['抓到啦！再来一次！']};bubble.textContent=lines[action][Math.floor(Math.random()*lines[action].length)];mood.textContent={pet:'被爱包围了',feed:'吃得心满意足',play:'开心得蹦蹦跳'}[action];icon.textContent='♡';animate(action==='play'?'play':'happy');hearts()}return {sleeping,mood:mood.textContent}}
pet.addEventListener('click',()=>{if(!moved)act('pet')});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));
pet.addEventListener('pointerdown',e=>{moved=false;down={x:e.clientX,y:e.clientY,left:pet.offsetLeft,top:pet.offsetTop};pet.setPointerCapture(e.pointerId)});pet.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>6)moved=true;if(moved){pet.style.marginLeft='0';pet.style.left=Math.max(-30,Math.min(room.clientWidth-pet.clientWidth+30,down.left+dx))+'px';pet.style.top=Math.max(150,Math.min(room.clientHeight-pet.clientHeight-20,down.top+dy))+'px'}});pet.addEventListener('pointerup',()=>down=null);pet.addEventListener('pointercancel',()=>down=null);pet.addEventListener('keydown',e=>{const steps={ArrowLeft:[-15,0],ArrowRight:[15,0],ArrowUp:[0,-15],ArrowDown:[0,15]};if(!steps[e.key])return;e.preventDefault();pet.style.marginLeft='0';pet.style.left=Math.max(-30,Math.min(room.clientWidth-210,pet.offsetLeft+steps[e.key][0]))+'px';pet.style.top=Math.max(150,Math.min(room.clientHeight-260,pet.offsetTop+steps[e.key][1]))+'px'});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'interact_with_kitten',description:'摸摸、喂食、玩耍，或切换小八睡觉状态。',inputSchema:{type:'object',properties:{action:{type:'string',enum:['pet','feed','play','sleep']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>act(input?.action)})).catch(()=>{})}catch{}}
